"""Seed the FoodWise database with demo data for the viva presentation.

Usage
-----
    python seed_demo.py          # create demo data if it does not exist
    python seed_demo.py --fresh  # wipe everything and rebuild

What you get
------------
* Demo account:  username  demo_user  /  password  Demo@123
* 11 active inventory items (5 expiring soon, 1 expired, 5 fresh)
* 10 historical waste records  ->  the ML panel is TRAINED (gate = 8)
* Reminders generated by the same expiry checker the app uses

The demo data is generated relative to today's date, so statuses and
reminders always look correct no matter when you run it.
"""
import os
import sys

# Build our own app instance instead of the auto-created one.
os.environ["FOODWISE_SKIP_APP_CREATION"] = "1"

from datetime import date, timedelta

from app import create_app, seed_default_recipes
from models import db, User, FoodItem, FoodWaste
from routes.notifications import run_expiry_check

DEMO_USERNAME = "demo_user"
DEMO_EMAIL = "demo@foodwise.app"
DEMO_PASSWORD = "Demo@123"

# name, category, quantity, unit, purchased_days_ago, expires_in_days
INVENTORY = [
    ("Milk",              "Dairy",      1,    "L",      2,   1),
    ("Bananas",           "Fruits",     1,    "kg",     3,   2),
    ("Greek Yogurt",      "Dairy",      500,  "g",      4,   3),
    ("Whole Wheat Bread", "Grains",     1,    "pack",   5,   0),
    ("Eggs",              "Dairy",      12,   "pcs",    6,   8),
    ("Chicken Breast",    "Meat",       0.5,  "kg",     1,   2),
    ("Carrots",           "Vegetables", 0.5,  "kg",     7,   12),
    ("Apples",            "Fruits",     1,    "kg",     7,   14),
    ("Basmati Rice",      "Grains",     5,    "kg",     30,  300),
    ("Tomato Ketchup",    "Other",      1,    "bottle", 60,  -5),
    ("Spinach",           "Vegetables", 200,  "g",      2,   2),
]

# name, category, wasted_qty, reason, purchased_days_ago, shelf_life_days,
# fraction of shelf life actually used (becomes the ML target)
WASTE_HISTORY = [
    ("Milk",           "Dairy",      1.0, "Expired",          20, 7,  1.00),
    ("Spinach",        "Vegetables", 0.2, "Spoiled",          15, 5,  0.90),
    ("Bread",          "Grains",     1.0, "Not used in time", 12, 5,  0.85),
    ("Yogurt",         "Dairy",      2.0, "Expired",          25, 10, 0.95),
    ("Tomatoes",       "Fruits",     0.4, "Spoiled",          18, 6,  0.80),
    ("Chicken Breast", "Meat",       0.8, "Expired",          10, 3,  1.00),
    ("Lettuce",        "Vegetables", 1.0, "Not used in time", 14, 7,  0.75),
    ("Strawberries",   "Fruits",     0.3, "Spoiled",          9,  4,  0.90),
    ("Cheese",         "Dairy",      0.5, "Over-purchased",   30, 21, 0.70),
    ("Orange Juice",   "Other",      1.0, "Expired",          40, 30, 0.85),
]


def main(fresh=False):
    app = create_app({"SCHEDULER_ENABLED": False})
    today = date.today()

    with app.app_context():
        if fresh:
            print("[FoodWise] --fresh: dropping all tables and rebuilding")
            db.drop_all()
            db.create_all()
            seed_default_recipes()

        user = User.query.filter_by(username=DEMO_USERNAME).first()
        if user is not None:
            print("[FoodWise] demo data already exists (user 'demo_user').")
            print("          Use  python seed_demo.py --fresh  to rebuild it.")
            return

        user = User(username=DEMO_USERNAME, email=DEMO_EMAIL)
        user.set_password(DEMO_PASSWORD)
        db.session.add(user)
        db.session.commit()

        # --- active inventory -------------------------------------------
        for name, category, qty, unit, purchased_ago, expires_in in INVENTORY:
            db.session.add(FoodItem(
                user_id=user.id,
                food_name=name,
                category=category,
                quantity=qty,
                unit=unit,
                purchase_date=today - timedelta(days=purchased_ago),
                expiry_date=today + timedelta(days=expires_in),
            ))
        db.session.commit()

        # --- historical waste (ML training data) -------------------------
        for name, category, qty, reason, purchased_ago, shelf, frac in WASTE_HISTORY:
            days_held = max(int(round(shelf * frac)), 0)
            waste_day = today - timedelta(days=purchased_ago - days_held)
            db.session.add(FoodWaste(
                user_id=user.id,
                food_name_snapshot=name,
                category_snapshot=category,
                wasted_quantity=qty,
                reason=reason,
                waste_date=waste_day,
                shelf_life_days=shelf,
                days_held=days_held,
            ))
        db.session.commit()

        # --- reminders via the real checker -------------------------------
        created = run_expiry_check()

        print()
        print("=" * 56)
        print(" FoodWise demo data seeded successfully")
        print("=" * 56)
        print(f" Login        : demo_user  /  Demo@123")
        print(f" Inventory    : {len(INVENTORY)} items "
              f"(expiring soon / expired / fresh all included)")
        print(f" Waste records: {len(WASTE_HISTORY)} "
              f"(ML gate is 8, so the ML panel is TRAINED)")
        print(f" Reminders    : {created} created")
        print(" Start the app:  python app.py   ->  http://127.0.0.1:5000")
        print("=" * 56)


if __name__ == "__main__":
    main(fresh="--fresh" in sys.argv)
